function isNsfwPromptText(promptText, allowNsfw) {
  if (allowNsfw) return true;
  if (!promptText) return false;
  const lower = promptText.toLowerCase();
  const nsfwKeywords = [
    "nsfw",
    "adult",
    "nude",
    "naked",
    "erotic",
    "sensual",
    "lingerie",
    "bikini",
    "swimsuit",
    "boudoir",
    "topless",
    "cock",
    "penis",
    "dick",
    "boobs",
    "breasts",
    "sexy",
    "flirty",
    "uncensored",
    "explicit",
    "intimate",
    "stripping",
    "strip"
  ];
  return nsfwKeywords.some((kw) => lower.includes(kw));
}
