app.post("/api/stitch-videos", async (req, res) => {
  const { videoUrls } = req.body;
  if (!Array.isArray(videoUrls) || videoUrls.length === 0) {
    return res.status(400).json({ error: "videoUrls array is required and must not be empty" });
  }
  try {
    const { execFile } = await import("child_process");
    const { promisify } = await import("util");
    const execFileAsync = promisify(execFile);
    const fs4 = await import("fs");
    const path2 = await import("path");
    const os = await import("os");
    const tmpDir = fs4.mkdtempSync(path2.join(os.tmpdir(), "stitch-"));
    const downloadedFiles = [];
    for (let i2 = 0; i2 < videoUrls.length; i2++) {
      const vUrl = videoUrls[i2];
      let buffer;
      if (vUrl.startsWith("data:")) {
        const base64Data = vUrl.split(",")[1];
        buffer = Buffer.from(base64Data, "base64");
      } else {
        const fetchRes = await fetch(vUrl);
        if (!fetchRes.ok) throw new Error(`Failed to download segment video ${i2 + 1}`);
        buffer = Buffer.from(await fetchRes.arrayBuffer());
      }
      const filePath = path2.join(tmpDir, `seg_${i2}.mp4`);
      fs4.writeFileSync(filePath, buffer);
      downloadedFiles.push(filePath);
    }
    const listPath = path2.join(tmpDir, "concat_list.txt");
    const fileListContent = downloadedFiles.map((f2) => `file '${f2}'`).join("\n");
    fs4.writeFileSync(listPath, fileListContent);
    const outputPath = path2.join(tmpDir, "stitched_output.mp4");
    await execFileAsync("ffmpeg", [
      "-f",
      "concat",
      "-safe",
      "0",
      "-i",
      listPath,
      "-c",
      "copy",
      "-y",
      outputPath
    ]);
    const outputBuffer = fs4.readFileSync(outputPath);
    const base64 = outputBuffer.toString("base64");
    const dataUrl = `data:video/mp4;base64,${base64}`;
    try {
      fs4.rmSync(tmpDir, { recursive: true, force: true });
    } catch {
    }
    return res.json({ videoUrl: dataUrl });
  } catch (err) {
    console.error("[stitch-videos] Error:", err);
    return res.status(500).json({ error: err.message || "Video stitching failed" });
  }
});
